// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // Fuzz the from address and the uint value; the distinguishing input is an empty _tos array.
    function testFuzz_property(address from, uint256 v) public {
        // Keep addresses in the regular non-zero domain to avoid degenerate zero-address assumptions
        vm.assume(from != address(0));

        address[] memory empty = new address[](0);

        // Call transfer with an empty _tos array. In the reference contract this MUST revert due to require(_tos.length > 0).
        // The mutant removed that require and will NOT revert for some inputs, returning true instead.
        bool ok;
        try c.transfer(from, address(0x1234), empty, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for ALL inputs, the reference reverts, so ok must be false.
        // The mutant violates this for some inputs (it returns true), so this assertion will fail on the mutant for some fuzzed values.
        assertTrue(!ok);
    }
}
